Given a singly linked list and a key, the task is to count the number of occurrences of the given key in the linked list. Example : Input : head: 1->2->1->2->1->3->1 , key = 1Output : 4 Explanation: key equals 1 has 4 occurrences.Input : head: 1->2->1->2->1, key = 3Output : 0Explanation: key equals to 3 has 0 occurrences.Try It YourselfTable of Content[Naive Approach] By Recursion – O(n) time and O(n) space[Expected Approach] By Traversing each node – O(n) time and O(1) space[Naive Approach] By Recursion – O(n) time and O(n) spaceThe idea is to recursively traverse the linked list from the head. At each node, check if its value matches the given key; if it does, increment the count by 1. Then recursively call the function on the next node. When the pointer reaches NULL, return 0. The total count is obtained by summing the matches from all recursive calls.
            C++

    #include <iostream>
using namespace std;

class Node {
public:
    int data;
    Node* next;
  	Node(int data) {
        this->data = data;
        this->next = nullptr;
    }
};

// Counts the no. of occurrences of a key 
// in a linked list
int count(struct Node* head, int key) {
    if (head == NULL)
        return 0;

  	int ans = count(head->next, key);

    if (head->data == key)
        ans++;

    return ans;
}

int main() {

    //Hard Coded Linked List 
  	// 1->2->1->2->1

    Node* head = new Node(1);
    head->next = new Node(2);
    head->next->next = new Node(1);
    head->next->next->next = new Node(2);
    head->next->next->next->next = new Node(1);

  	int key = 1;

    cout << count(head, key);
    return 0;
}


